/* Per-cell statistics in the Analysis step: cells nested in wells, the well as a random effect.
 *
 * The reference numbers are R's nlme::lme(y ~ group, random = ~1|subject) on PlotMate's nested
 * data sets (PlotMate/tests/reference/ref_r.js, generated by gen_r.R). Rule fixed before running:
 * t, F and P within 1e-5 relative of R; degrees of freedom exactly R's. */
(function () {
  const rel = (a, b, tol, m) => { if (!(Math.abs(a - b) <= tol * Math.max(Math.abs(b), 1e-300))) throw new Error((m || '') + ' expected ' + b + ' got ' + a); };
  const R = () => window.REF_R && window.REF_R.multivar;
  const nestedSpec = (key, names) => ({ nested: true, compare: 'all', groups: DS[key].groups.map((wells, i) => ({
    name: names[i], values: wells.map(c => c.reduce((a, v) => a + v, 0) / c.length), cells: wells })) });

  test('cells: nested t test and nested one-way ANOVA match R nlme', () => {
    if (!R()) throw new Error('PlotMate/tests/reference/ref_r.js not loaded');
    [['nested2', ['A', 'B']], ['nested_unbal', ['A', 'B']]].forEach(([k, names]) => {
      const st = FM.groupStats.run(nestedSpec(k, names)), ref = R()[k];
      eq(st.test.kind, 'nested-t', k);
      rel(Math.abs(st.test.t), Math.abs(ref.t), 1e-5, k + ' t');
      rel(st.test.p, ref.tp, 1e-5, k + ' P');
      eq(st.test.df, ref.tdf, k + ' df = wells − conditions');
      eq(st.comparisons.length, 1);
      rel(st.comparisons[0].diff, ref.means[0] - ref.means[1], 1e-6, k + ' difference of model means');
    });
    const st = FM.groupStats.run(nestedSpec('nested3', ['A', 'B', 'C'])), ref = R().nested3;
    eq(st.test.kind, 'nested-anova');
    rel(st.test.F, ref.F, 1e-5, 'F'); rel(st.test.p, ref.p, 1e-5, 'P'); eq(st.test.dfd, ref.dfd, 'denominator df');
    eq(st.comparisons.length, 3, 'Tukey: every pair');
    assert(st.comparisons.every(c => c.p >= 0 && c.p <= 1), 'adjusted P in [0, 1]');
    eq(st.fit.wells, 12); eq(st.fit.cells, 48);
    eq(st.summary[0].wells, 4); eq(st.summary[0].cells, 16);
  });

  test('cells: a condition with one well is not tested — its cells are not replicates', () => {
    const st = FM.groupStats.run({ nested: true, compare: 'all', groups: [
      { name: 'A', values: [1], cells: [[1, 2, 3, 4, 5, 6, 7, 8]] },
      { name: 'B', values: [9], cells: [[8, 9, 10, 11, 12, 13, 14, 15]] }] });
    eq(st.test, null, 'no test');
    assert(st.notes.some(n => /at least 2 wells/.test(n)), 'says why: ' + st.notes.join(' | '));
  });

  test('cells: unlike pooling cells, the nested test does not turn one odd well into significance', () => {
    // three wells per condition, no real difference, one well of B shifted: pooling 300 cells per
    // condition would call it significant; the nested test, with the well as the replicate, must not
    let seed = 7; const rnd = () => { seed = (seed * 16807) % 2147483647; return seed / 2147483647; };
    const normal = () => Math.sqrt(-2 * Math.log(rnd())) * Math.cos(2 * Math.PI * rnd());
    const well = shift => Array.from({ length: 100 }, () => 10 + shift + normal());
    const A = [well(0), well(0.3), well(-0.3)], B = [well(0.2), well(-0.2), well(1.5)];
    const pooled = PM.ttest.unpaired([].concat(...A), [].concat(...B), { welch: false });
    assert(pooled.p < 0.001, 'pooled cells look very significant (that is the trap): P = ' + pooled.p);
    const st = FM.groupStats.run({ nested: true, compare: 'all', groups: [
      { name: 'A', values: A.map(c => c.reduce((a, v) => a + v, 0) / c.length), cells: A },
      { name: 'B', values: B.map(c => c.reduce((a, v) => a + v, 0) / c.length), cells: B }] });
    assert(st.test.p > 0.05, 'nested: not significant, P = ' + st.test.p);
    eq(st.test.df, 4, 'df from 6 wells, not 600 cells');
  });

  test('graphs: per-cell mode tests the population\'s events, nested in wells', () => {
    const g = twoGroupWs(400);
    const P = wideRange(g.ws, null, 'Cells');
    const t = g.ws.addTable('T');
    g.ws.addTableColumn(t, { pop: P, stat: 'mean', param: 'FSC-H' });
    g.ws.addTableColumn(t, { pop: P, stat: 'freq_parent' });
    const [cMean, cFreq] = g.ws.table(t).columns.map(c => c.id);
    const spec = Object.assign(FM.graphs.create(g.ws, { table: t, col: cMean }), { unit: 'cell' });
    const r = FM.graphs.compute(g.ws, spec);
    assert(r.nested, 'nested');
    eq(r.stats.test.kind, 'nested-t');
    eq(r.stats.fit.wells, 6);
    const cells = ['A1', 'A2', 'A3', 'B1', 'B2', 'B3'].reduce((a, k) => a + g.ws.count(g.ws.sample(k), P), 0);
    eq(r.stats.fit.cells, cells, 'every event of the population in the six wells');
    eq(r.model.groups[0].values.length, 3, 'the graph still shows one dot per well');
    // the model's mean for a condition is a weighted mean of its cells: between the well means
    const wm = ['A1', 'A2', 'A3'].map(k => FM.graphs.cellValues(g.ws, k, g.ws.table(t).columns[0]).values).map(v => v.reduce((a, x) => a + x, 0) / v.length);
    const m = r.stats.fit.means[0];
    assert(m >= Math.min(...wm) - 1e-9 && m <= Math.max(...wm) + 1e-9, 'model mean within the well means');
    // a frequency column has no per-cell value: falls back to wells, and says so
    const r2 = FM.graphs.compute(g.ws, Object.assign(FM.graphs.create(g.ws, { table: t, col: cFreq }), { unit: 'cell' }));
    assert(!r2.nested && r2.stats.test.kind === 't', 'tested per well');
    assert(r2.notes.some(n => /Tested per well instead/.test(n)), 'note');
  });

  test('graphs: median and geometric mean columns are tested on log10 of the cells', () => {
    const g = twoGroupWs(300);
    const P = wideRange(g.ws, null, 'Cells');
    const t = g.ws.addTable('T');
    g.ws.addTableColumn(t, { pop: P, stat: 'gmean', param: 'FL1-H' });
    const col = g.ws.table(t).columns[0];
    const r = FM.graphs.compute(g.ws, Object.assign(FM.graphs.create(g.ws, { table: t, col: col.id }), { unit: 'cell' }));
    eq(r.cellScale, 'log');
    const v = FM.graphs.cellValues(g.ws, 'A1', col);
    const raw = g.ws.indices(g.ws.sample('A1'), P);
    const pos = Array.from(raw).filter(i => g.ws.sample('A1').data['FL1-H'][i] > 0);
    eq(v.values.length, pos.length, 'positive events kept');
    eq(v.dropped, raw.length - pos.length, 'the rest counted as dropped');
    approx(v.values[0], Math.log10(g.ws.sample('A1').data['FL1-H'][pos[0]]), 1e-12);
  });
})();
